        for (int i = start; i < nums.length; i++) {
            int temp = nums[start];
            nums[start] = nums[i];
            nums[i] = temp;
            current.add(nums[start]);
            permuteHelper(result, current, nums, start + 1);
            current.remove(current.size() - 1);
            nums[start] = nums[i];
            nums[i] = temp;
        }
