import java.util.*;

public int findLargestSubstring(List<String> strings) {
    int maxLen = 0;
    for (int len = strings.size(); len > 0; len--) {
        for (int start = 0; start <= strings.size() - len; start++) {
            String candidate = strings.get(start);
            if (!candidate.equals(candidate.reverse())) {
                if (isSubsequence(candidate, strings) || isSubsequence(candidate.reverse(), strings)) {
                    return len;
                }
            }
        }
    }
    return 0;
}

private boolean isSubsequence(String subseq, List<String> strings) {
    int subseqIndex = 0;
    for (String str : strings) {
        int strIndex = 0;
        while (strIndex < str.length() && subseqIndex < subseq.length() && str.charAt(strIndex) == subseq.charAt(subseqIndex)) {
            strIndex++;
            subseqIndex++;
        }
        if (subseqIndex == subseq.length()) {
            return true;
        }
    }
    return false;
}
