import java.util.List;
import java.util.HashSet;
import java.util.Set;

public int findLargestSubstring(List<String> strings) {
    Set<String> seen = new HashSet<>();
    int maxSize = 0;

    for (String str : strings) {
        Set<Character> charSet = new HashSet<>();
        for (char c : str.toCharArray()) {
            charSet.add(c);
        }

        for (String inverse : getInverses(str)) {
            if (seen.add(inverse)) {
                maxSize = Math.max(maxSize, inverse.length());
            }
        }

        seen.add(str);
    }

    return maxSize;
}

private List<String> getInverses(String str) {
    List<String> inverses = new ArrayList<>();
    StringBuilder reversed = new StringBuilder(str);
    for (int i = 0; i < str.length() / 2; i++) {
        char temp = reversed.charAt(i);
        reversed.setCharAt(i, reversed.charAt(str.length() - i - 1));
        reversed.setCharAt(str.length() - i - 1, temp);
    }
    inverses.add(str);
    inverses.add(reversed.toString());

    return inverses;
}
