private void reverseString(String s) {
    char[] arr = s.toCharArray();
    for (int i = 0, j = arr.length - 1; i < j; i++, j--) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

private boolean isSubstringAvailable(String str, List<String> allStrings) {
    for (String otherStr : allStrings) {
        if (otherStr.contains(str) || otherStr.contains(new StringBuilder(str).reverse().toString())) {
            return true;
        }
    }
    return false;
