    int rows = grid.length;
    int cols = Rows > 0 ? grid[0].length : 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                fillWithOil(grid, i, j);
            }
        }
    }

    return count;
}

private static void fillWithOil(char[][] grid, int row, int col) {
    if (row >= 0 && row < grid.length && col >= 0 && col < grid[0].length && grid[row][col] == '@') {
        grid[row][col] = '#'; // Mark as visited
        fillWithOil(grid, row - 1, col); // Up
        fillWithOil(grid, row + 1, col); // Down
        fillWithOil(grid, row, col - 1); // Left
        fillWithOil(grid, row, col + 1); // Right
    }
}
