public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end coordinates are valid indices
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "Invalid coordinates";
    }

    // Map to store adjacent n-tersections
    boolean[][] adjList = new boolean[n][n];

    // Populate the adjacent list from the paths
    for (int i = 0; i < paths.length; i++) {
        adjList[paths[i][0]][paths[i][1]] = true;
        adjList[paths[i][1]][paths[i][0]] = true;
    }

    // Depth-First Search (DFS) to check if the path exists
    return dfs(n, adjList, start[0], start[1], end[0], end[1]) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int n, boolean[][] adjList, int x, int y, int targetX, int targetY) {
    // Base case: reached the target
    if (x == targetX && y == targetY) {
        return true;
    }

    // Ensure we stay within the bounds
    if (x < 0 || x >= n || y < 0 || y >= n) {
        return false;
    }

    // Mark the current cell as visited
    adjList[x][y] = false;

    // Explore all adjacent cells
    if (dfs(n, adjList, x + 1, y, targetX, targetY) || dfs(n, adjList, x - 1, y, targetX, targetY) || dfs(n, adjList, x, y + 1, targetX, targetY) || dfs(n, adjList, x, y - 1, targetX, targetY)) {
        return true;
    }

    // Reset the current cell as unvisited
    adjList[x][y] = true;

    return false;
}
