private static boolean canTravelMaze(int[] start, int[] end, int[][] paths, boolean[][] visited) {
    int x1 = start[0], y1 = start[1], x2 = end[0], y2 = end[1];
    Queue<int[]> q = new LinkedList<>();
    q.add(new int[]{x1, y1});
    visited[x1][y1] = true;

    while (!q.isEmpty()) {
        int[] current = q.poll();

        if (current[0] == x2 && current[1] == y2) {
            return "can be travelled";
        }

        for (int[] direction : new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
            int x = current[0] + direction[0], y = current[1] + direction[1];

            if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
                continue;
            }

            if (isAdjacent(current, x, y, paths)) {
                visited[x][y] = true;
                q.add(new int[]{x, y});
            }
        }
    }

    return "cannot be travelled";
}

private static boolean isAdjacent(int[] current, int x, int y, int[][] paths) {
    for (int[] path : paths) {
        if (path[0] == current[0] && path[1] == current[1]) {
            int[] other = path[1] < current[1] ? path : new int[]{path[1], path[0]};
            int newX = other[0] - current[0], newY = other[1] - current[1];
            if (newX == 1 && newY == 0 || newX == -1 && newY == 0 || newX == 0 && newY == 1 || newX == 0 && newY == -1) {
                return true;
            }
        }
    }
    return false;
}
