public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();

    visited[start[0]][start[1]] = true;
    queue.offer(start);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] neighbor : getPath(start, end, paths)) {
            if (!visited[neighbor[0]][neighbor[1]]) {
                visited[neighbor[0]][neighbor[1]] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

private static int[][] getPath(int[] start, int[] end, int[][] paths) {
    List<int[]> pathList = new ArrayList<>();
    int[] curr = start;
    do {
        pathList.add(curr);
        int[] next = findPath(curr, paths);
        if (next == null) {
            break;
        }
        curr = next;
    } while (!Arrays.equals(curr, end));

    pathList.add(end);
    Collections.reverse(pathList);
    return pathList.toArray(new int[pathList.size()][]);
}

private static int[] findPath(int[] curr, int[][] paths) {
    for (int[] path : paths) {
        if (path[0] == curr[0] && path[1] == curr[1]) {
            return path;
        }
    }
    return null;
}
