    reduced.append(word1);
    reduced.append(", ");
    reduced.append(word2);
    reduced.append(") = ");
    reduced.append((commonChars / gcd).toString());
    reduced.append(" / ");
    reduced.append((length1 + length2) / gcd).toString();

    return reduced.toString();
}

private static int getGCD(int a, int b) {
    if (b == 0) {
        return a;
    }
    return getGCD(b, a % b);
