public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create the adjacency list representation of the tree
    ArrayList<ArrayList<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Initialize the dp array which keeps track of the minimum time to collect apples starting from each node
    int[] dp = new int[n];
    Arrays.fill(dp, Integer.MAX_VALUE);

    // Define a helper function to perform depth-first search starting from a node
    dfs(graph, n, dp, hasApple, 0);

    // As per the problem description, return the cost of returning to the starting node
    return dp[0];
}

// Helper function to perform depth-first search
private void dfs(ArrayList<ArrayList<Integer>> graph, int n, int[] dp, boolean[] hasApple, int node) {
    // Base case: if the current node is a leaf (no children)
    if (graph.get(node).size() == 0) {
        dp[node] = 0; // No operations needed, return 0 time
        return;
    }

    // Initialize minimum cost to the maximum possible value
    dp[node] = Integer.MAX_VALUE;

    // Iterate over each child of the current node
    for (int child : graph.get(node)) {
        // If the child has an apple or we are in a frame of recursion for the child
        if (hasApple[child] || dp[child] == -1) {
            dp[node] = Math.min(dp[node], dfs(graph, n, dp, hasApple, child) + 2);
        }
    }

    // If the current node can be used in the path (starting from the sibling)
    if (hasApple[node] && dp[node] != -1) {
        dp[node] = 2 + dp[node];
    }

    // Store the results to avoid recomputation
    if (dp[node] == Integer.MAX_VALUE) {
        dp[node] = -1;
    }
    return dp[node];
}
