    dp[0] = 0; // Starting from node 0, it takes 0 time to reach it

    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        dp[v] = Math.min(dp[v], dp[u] + 2); // Update the minimum time to reach node v from node u
    }

    for (int i = 0; i < n; i++) {
        if (dp[i] > 2 && !hasApple[i]) {
            dp[i] = dp[i] - 2; // Subtract 2 if the node has no apple
        }
    }

    return dp[0]; // Return the minimum time to reach node 0
