private int helper(Map<Integer, List<Integer>> graph, boolean[] hasApple, int node, boolean[] visited, int[] dp) {
    if (dp[node] != 0) return dp[node];

    visited[node] = true;
    int totalTime = 0;

    for (int neighbor : graph.getOrDefault(node, new ArrayList<>())) {
        if (!visited[neighbor]) {
            totalTime += helper(graph, hasApple, neighbor, visited, dp);
        }
    }

    if (hasApple[node]) {
        totalTime += 2;
    }

    visited[node] = false;
    dp[node] = totalTime;
    return totalTime;
}
