public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    Set<Character> used_chars = new HashSet<>();

    while (!s.isEmpty()) {
        // Step 1: Pick the smallest character
        char smallest = s.charAt(0);
        for (char c : s.toCharArray()) {
            if (c < smallest && !used_chars.contains(c)) {
                smallest = c;
            }
        }
        result.append(smallest);
        used_chars.add(smallest);
        s = s.replaceFirst("" + smallest, "");

        // Step 2: Pick the smallest character greater than the last appended character
        char next_smallest = s.charAt(0);
        for (char c : s.toCharArray()) {
            if (c < next_smallest && !used_chars.contains(c)) {
                next_smallest = c;
            }
        }
        result.append(next_smallest);
        used_chars.add(next_smallest);
        s = s.replaceFirst("" + next_smallest, "");

        // Step 3: Repeat step 2 until you cannot pick more characters
        s = pickRemaining(s, used_chars, 'L');

        // Step 4: Pick the largest character
        char largest = s.charAt(0);
        for (char c : s.toCharArray()) {
            if (c > largest && !used_chars.contains(c)) {
                largest = c;
            }
        }
        result.append(largest);
        used_chars.add(largest);
        s = s.replaceFirst("" + largest, "");

        // Step 5: Pick the largest character smaller than the last appended character
        char next_largest = s.charAt(0);
        for (char c : s.toCharArray()) {
            if (c > next_largest && !used_chars.contains(c)) {
                next_largest = c;
            }
        }
        result.append(next_largest);
        used_chars.add(next_largest);
        s = s.replaceFirst("" + next_largest, "");

        // Step 6: Repeat step 5 until you cannot pick more characters
        s = pickRemaining(s, used_chars, 'R');
    }

    return result.toString();
}

private String pickRemaining(String s, Set<Character> used_chars, char order) {
    StringBuilder remaining = new StringBuilder();
    for (char c : s.toCharArray()) {
        if (!used_chars.contains(c)) {
            if (order == 'L' && c <= remaining.charAt(remaining.length() - 1)) {
                remaining.append(c);
            } else if (order == 'R' && c >= remaining.charAt(remaining.length() - 1)) {
                remaining.append(c);
            }
        }
    }
    return remaining.toString();
}
