            if (i < chars.length - 1 && chars[i] != chars[i + 1]) {
                continue;
            }
            break;
        }
        for (int i = chars.length - 1; i >= 0; i--) {
            result.append(chars[i]);
            if (i > 0 && chars[i] != chars[i - 1]) {
                continue;
            }
            break;
