public boolean hasAllCodes(String s, int k) {
    // Check if k is greater than s.length.
    if (k > s.length()) return false;

    int mask = (1 << k) - 1; // Generate a bitmask with k ones to track occurrences.

    // Create a set to store all possible substrings of length k.
    Set<String> seen = new HashSet<>();

    // Split s into substrings of length k.
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        // Check if the substring is already in the set.
        if (seen.contains(substring)) return false;
        // Add the substring to the set.
        seen.add(substring);
    }

    // If all substrings of length k are found in s, return true.
    return true;
