public int minInsertions(String s) {
    int balance = 0; // Track the balance of '(' and ')'
    int insertions = 0; // Keep track of the number of insertion operations

    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++; // Increment balance if we encounter a '(' bracket
        } else if (c == ')') {
            balance--; // Decrement balance if we encounter a ')' bracket
        }

        if (balance < 0) {
            // If balance is negative, we need to insert a '(' at the current position
            // 1. Increase the number of insertion operations by '('
            // 2. Recur the function to balance the current bracket
            insertions++;
            balance++;
        }
    }

    // Return the total number of insertions plus the absolute value of the balance
    return insertions + Math.abs(balance);
}
