public int findMinFibonacciNumbers(int k) {
    // Initialize a set to store Fibonacci numbers up to k
    Set<Integer> fibs = new HashSet<>();
    // Generate Fibonacci numbers up to k and store in the set
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int nextFib = fibs.last() + fibs.get(fibs.size() - 2);
        if (nextFib > k) break;
        fibs.add(nextFib);
    }
    // Use dynamic programming to find the minimum count of Fibonacci numbers
    int[] DP = new int[k + 1];
    Arrays.fill(DP, Integer.MAX_VALUE);
    DP[0] = 0;
    for (int fib : fibs) {
        for (int x = fib; x <= k; x++) {
            DP[x] = Math.min(DP[x], DP[x - fib] + 1);
        }
    }
    return DP[k];
}
