        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                result.add(num);
            }
            int lastDigit = num % 10;
            if (lastDigit != 0) {
                int smaller = num * 10 + lastDigit - 1;
                if (smaller >= low && smaller <= high) {
                    queue.offer(smaller);
                }
            }
            if (lastDigit != 9) {
                int bigger = num * 10 + lastDigit + 1;
                if (bigger >= low && bigger <= high) {
                    queue.offer(bigger);
                }
            }
        }

        result.sort(Integer::compareTo);
        return result;
    }
}
