public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int[][] maxDiag = new int[m + n][1];
    int[][] maxAntiDiag = new int[m + n][1];

    int maxLine = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 0) {
                maxDiag[i + j] = 0;
                maxAntiDiag[i + j] = 0;
            } else {
                if (i == 0 || j == 0) {
                    maxDiag[i + j] = 1;
                    maxAntiDiag[i + j] = 1;
                } else {
                    maxDiag[i + j] = maxDiag[i + j - 1] + 1;
                    maxAntiDiag[i + j] = maxAntiDiag[i + j - 1] + 1;
                }

                maxLine = Math.max(maxLine, maxDiag[i + j]);
                maxLine = Math.max(maxLine, maxAntiDiag[i + j]);
            }
        }
    }

    return maxLine;
}
