public static int longestLine(int[][] mat) {
    int m = mat.length;
    if (m == 0) return 0;
    int n = mat[0].length;
    if (n == 0) return 0;

    // Array to store the length of the longest increasing diagonal
    int[] upDiag = new int[n];
    // Array to store the length of the longest decreasing diagonal
    int[] downDiag = new int[n];
    // Array to store the length of the longest horizontal line
    int[] horizontal = new int[n];
    // Array to store the length of the longest vertical line
    int[] vertical = new int[m];

    int maxLength = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            // Update incoming cells as the longest increasing or decreasing diagonal
            if (mat[i][j] == 1) {
                upDiag[j] = horizontal[j] + 1;
                downDiag[j] = vertical[i] + 1;
                vertical[i] = 1;
                horizontal[j] = 1;
                maxLength = Math.max(maxLength, Math.max(upDiag[j], downDiag[j]));
            }
        }
    }

    return maxLength;
}
