    // Check horizontal lines
    for (int i = 0; i < mat.length; i++) {
        int currentMax = 0;
        for (int j = 0; j < mat[i].length; j++) {
            if (mat[i][j] == 1) currentMax++;
            else currentMax = 0;
            max = Math.max(max, currentMax);
        }
    }

    // Check vertical lines
    for (int j = 0; j < mat[0].length; j++) {
        int currentMax = 0;
        for (int i = 0; i < mat.length; i++) {
            if (mat[i][j] == 1) currentMax++;
            else currentMax = 0;
            max = Math.max(max, currentMax);
        }
    }

    // Check diagonal lines
    int d1Max = 0, d2Max = 0;

    for (int i = mat.length - 1, j = 0; i >= 0; i--, j++) {
        if (mat[i][j] == 1) d1Max++;
        else d1Max = 0;
        max = Math.max(max, d1Max);
    }

    for (int i = 0, j = mat[0].length - 1; i < mat.length && j >= 0; i++, j--) {
        if (mat[i][j] == 1) d2Max++;
        else d2Max = 0;
        max = Math.max(max, d2Max);
    }

    return max;
