public static void permute(int[] A, int start, int count) {
    if (start == A.length) {
        count++;
        return;
    }
    for (int i = start; i < A.length; i++) {
        if (isValid(A, start, i)) {
            swap(A, start, i);
            permute(A, start + 1, count);
            swap(A, start, i);
        }
    }
}

public static boolean isValid(int[] A, int start, int end) {
    return isPerfectSquare(A[start] + A[end]);
}

public static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

public static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}
