        permutations.add(new ArrayList<>(Lists.newArrayList(nums)));
        return;
    }
    for (int i = index; i < nums.length; i++) {
        swap(nums, index, i);
        permute(nums, index + 1, permutations);
        swap(nums, index, i);
    }
}

