public static int squarePermutations(int[] A) {
    int result = 0;
    int n = A.length;

    // Check if the sum of each pair of adjacent elements is a perfect square
    for (int i = 0; i < n - 1; i++) {
        int sum = A[i] + A[i + 1];
        if (!isPerfectSquare(sum)) {
            return 0;
        }
    }

    // Check if the array can be permuted in a way that each pair of adjacent elements sum to a perfect square
    if (canFormSquarePermutation(A)) {
        result++;
    }

    // Try each permutation of the array
    for (int i = 0; i < n; i++) {
        int temp = A[i];
        swap(A, i, n - 1);
        if (canFormSquarePermutation(A)) {
            result++;
        }
        swap(A, i, n - 1);
    }

    return result;
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static void swap(int[] arr, int i, int j) {
