    int len = A.length;
    int result = 1;
    if (numPerms[len-1] == -1) {
        populate(NUMPERMS, PERMUTATION_SIZE, len-1, 11);
    }
    int oldIdx = -1;
    for (int i = len-1; i > 0; i--) {
        if (sumOfNeighboring(A[i-1], A[i]) == 0) {
            if (oldIdx == i-1) continue;
            int prevSum = 0;
            while (prevSum < sumOfNeighboring(A[i-1], A[i-2])) prevSum += NUMPERMS[len-1-mod((i-1)%len)];
            int remain = 0;
            if ((i+1)%len == 0) remain = PERMUTATION_SIZE[PERM_IDX] - NUMPERMS[len-1-mod((i-1)%len)];
            result += ((i+1)%len == 0 ? 0 : mid(prevSum+remain, oldIdx+1, PERMUTATION_SIZE[PERM_IDX]));
            remain = oldIdx - i+1;
            result += oldIdx + 1 <= PERMUTATION_SIZE[PERM_IDX] - (i+1)%len ? ((i+1)%len == 0 ? 0 : mid(remain, oldIdx+1, PERMUTATION_SIZE[PERM_IDX])) : 0;
            oldIdx = i-1;
        }
    }
    return (oldIdx == -1 && A[0] satisfiesCondition) ? result * 4 : (oldIdx == -1 && !A[0] satisfiesCondition) ? result : result * 2;
}

private static boolean satisfiesCondition(int num) {
    int sqrt = (int)Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static int mid(int a, int b, int size) {
    int dist = b - a + 1;
    if (dist % 2 == 0) return a + dist / 2 - 1;
    else return a + dist / 2;
}

private static void populate(int[] nums, int[] perms, int end, int perm_idx) {
    if (end == 0) {
        NUMPERMS[end] = perms[perm_idx];
        PERMUTATION_SIZE[perm_idx] = end + 1;
    } else {
        populate(nums, perms, end - 1, perm_idx);
        for (int i = 0; i < end && mid(i, end-1, perms[perm_idx]) - mid(i-1, end-1, perms[perm_idx]) < 0; i++) {
            int[] swap = nums[i-1], temp = nums[end];
            nums[i-1] = temp;
            nums[end] = swap;
            populate(nums, perms, end - 1, perm_idx + 1);
            nums[i-1] = swap;
            nums[end] = temp;
        }
    }
}
