public static int[] diagonalOrder(int[][] mat) {
    int rowCount = mat.length;
    int colCount = mat[0].length;
    List<Integer> result = new ArrayList<>();
    int row = 0;
    int col = 0;
    while (row < rowCount && col < colCount) {
        // Right side of the first row
        while (col < colCount) {
            result.add(mat[row][col]);
            row++;
            col++;
        }
        if (row == rowCount) break;

        // Diagonal downwards
        row = rowCount - 2;
        col++;
        while (col < colCount) {
            result.add(mat[row][col]);
            row--;
            col++;
        }

        // Left side of the last column
        row++;
        while (row < rowCount) {
            result.add(mat[row][col]);
            row++;
            col--;
        }
    }

    // Convert List to int[]
    int[] orderedArray = new int[result.size()];
    for (int i = 0; i < result.size(); i++) {
        orderedArray[i] = result.get(i);
    }
    return orderedArray;
}
