        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    boolean isDown = true;
    int totalElements = rows * cols;
    int[] result = new int[totalElements];

    for (int i = 0; i < totalElements; i++) {
        int x = i % cols;
        int y = i / cols;
        if (isDown) {
            result[i] = mat[y][x];
            if (x == cols - 1 && y < rows - 1) {
                isDown = false;
                y++;
            } else if (x == 0 && y >= 1) {
                isDown = false;
                y--;
            }
        } else {
            result[i] = mat[y][cols - 1 - x];
            if (y == rows - 1 && x < cols - 1) {
                isDown = true;
                x++;
            } else if (y == 0 && x >= 1) {
                isDown = true;
                x--;
            }
        }
    }

    return result;
