public static int[] diagonalOrder(int[][] mat) {
    if (mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxDiagonalLength = Math.max(rows, cols);
    int[] diagonalOrder = new int[maxDiagonalLength * 2 - 1];

    for (int i = 0; i < maxDiagonalLength; i++) {
        int r = Math.min(i, rows - 1);
        int c = Math.max(0, i - rows + 1);
        int index = i - r;

        if (i < cols - 1) {
            diagonalOrder[index] = mat[r][c];
        }

        if (i == cols - 1 && r < rows - 1) {
            diagonalOrder[maxDiagonalLength - index - 1] = mat[r][c];
        }
    }

    return diagonalOrder;
}
