public static int findSmallestInteger(int n) {
    char[] array = String.valueOf(n).toCharArray();
    int len = array.length;
    Arrays.sort(array); // Sort the array in ascending order.

    // Find the first pair of adjacent digits that are out of order (a, b) such that a > b.
    int i = len - 2;
    while (i >= 0 && array[i] > array[i + 1]) {
        i--;
    }

    if (i == -1) {
        return -1; // If no such pair exists, the number is already in ascending order, no possible solution.
    }

    // Find the smallest integer greater than array[i] that is less than array[i + 1].
    boolean adjacent = false;
    for (int j = len - 1; j >= i; j--) {
        if (array[j] > array[i] && (i == len - 2 || array[j] < array[i + 1])) {
            array[i] = array[j]; // Swap array[i] with array[j].
            Arrays.sort(array, i + 1, len); // Sort the rest of the array starting from i + 1.
            adjacent = true;
            break;
        }
    }

    // If no adjacent pair is found (which should not happen in this implementation), the number has no smaller permutation.
    if (!adjacent) {
        return -1;
    }

    // Convert the array back to an integer and return.
    return Integer.parseInt(new String(array));
}
