public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0; // Return 0 for the case where n is 0 or less
    }

    int[] dp = new int[n]; // Array to store the ugly numbers
    dp[0] = 1; // The first ugly number is 1


    int a = 0; // Index of the last generated ugly number from array '2'
    int b = 0; // Index of the last generated ugly number from array '3'
    int c = 0; // Index of the last generated ugly number from array '5'

    // Generate ugly numbers up to the nth ugly number
    for (int i = 1; i < n; i++) {
        int nextMultipleOf2 = dp[a] * 2;
        int nextMultipleOf3 = dp[b] * 3;
        int nextMultipleOf5 = dp[c] * 5;

        // Find the minimum of the next multiple of 2, 3, and 5 and store it in dp[i]
        dp[i] = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));

        // Move pointers for the next multiples if the current ugly number was the next multiple of 2, 3, or 5
        if (dp[i] == nextMultipleOf2) {
            a++;
        }
        if (dp[i] == nextMultipleOf3) {
            b++;
        }
        if (dp[i] == nextMultipleOf5) {
            c++;
        }
    }

    return dp[n - 1]; // Return the nth ugly number
}
