public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    helper(1, n, result, 0);
    return result;
}

private static void helper(int Lo, int Hi, List<Integer> res, int cur) {
    if (cur > Hi) return; // pruning, if the cur value is larger than hi, finish backtracking
    res.add(cur); // fill the current node cur into the result list
    for (int i = 1; i <= 9; i++) {
        int next = cur * 10 + i; // expand `cur` unit by one to get next cur
        if (next <= Hi) helper(Lo, Hi, res, next); // DFS, get next cur
    }
}
