        for (int i = 0; current <= n; i++) {
            result.add(current);
            if (current % 10 != 9 && current + 1 <= n) {
                current *= 10;
            } else if (current % 10 == 9) {
                current += 1;
                for (int j = 0; j < 9 && current <= n; j++) {
                    current += 1;
                    result.add(current);
