    int[] dp = new int[n + 1];
    Arrays.fill(dp, n); // Initialize dp array with maximum possible values

    // Base case: 0 perfect squares needed for 0
    dp[0] = 0;

    // Iterate through each number up to n
    for (int i = 1; i <= n; i++) {
        // Consider all perfect squares less than or equal to i
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}
