public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int[] squares = getPerfectSquares(i);
        int min = Integer.MAX_VALUE;
        for (int square : squares) {
            if (i - square >= 0) {
                min = Math.min(min, dp[i - square] + 1);
            }
        }
        dp[i] = min;
    }

    return dp[n];
}

private static int[] getPerfectSquares(int n) {
    int[] square = new int[100]; // Limit the number of squares to 100 to avoid overflow
    int j = 0;
    for (int i = 1; i * i <= n; i++) {
        square[j++] = i * i;
    }
    return Arrays.copyOf(square, j);
}
