public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int len = s.length();
    StringBuilder sb = new StringBuilder();
    int i = 0;

    while (i < len) {
        // Skip leading spaces
        while (i < len && s.charAt(i) == ' ') {
            i++;
        }
        int start = i;

        // Reverse the word
        if (i < len) {
            while (i < len && s.charAt(i) != ' ') {
                i++;
            }
            sb.append(new String(s.substring(start, i).toCharArray()));
        }

        // Append a single space
        sb.append(" ");
    }

    return sb.toString().trim();
}
